  "title": "Vizhi TiVi Public Streams v1",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "streams"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "streams": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/stream"
      }
    }
  },
  "$defs": {
    "stream": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "channelId",
        "url",
        "format",
        "playbackStatus",
        "lastVerifiedAt",
        "rightsEvidenceUrl"
      ],
      "properties": {
        "id": {
          "type": "string"
