            "verified",
            "experimental"
          ]
        },
        "lastVerifiedAt": {
          "type": "string",
          "format": "date"
        },
        "rightsEvidenceUrl": {
          "type": "string",
          "format": "uri"
        }
      }
    }
  }
}

